def _frac_det(M):
    """exact determinant by fraction Gaussian elimination."""
    n = len(M)
    if n == 0:
        return _Fr(1)
    A = [row[:] for row in M]
    det = _Fr(1)
    for c in range(n):
        piv = next((r for r in range(c, n) if A[r][c] != 0), None)
        if piv is None:
            return _Fr(0)
        if piv != c:
            A[c], A[piv] = A[piv], A[c]
            det = -det
        det *= A[c][c]
        inv = _Fr(1) / A[c][c]
        for r in range(c + 1, n):
            f = A[r][c] * inv
            if f != 0:
                for k in range(c, n):
                    A[r][k] -= f * A[c][k]
    return det


def _moms(nodes, wts, K):
    return [sum(w * x ** k for w, x in zip(wts, nodes))
            for k in range(K + 1)]


def _hankel_dets(nodes, wts, kmax):
    """D_0 = 1, D_k = det H_k of the signed measure, k = 1..kmax."""
    m = _moms(nodes, wts, 2 * kmax)
    out = [_Fr(1)]
    for k in range(1, kmax + 1):
        out.append(_frac_det([[m[i + j] for j in range(k)]
                              for i in range(k)]))
    return out


def _chain_from_dets(D):
    """pivot chain h_n = D_{n+1}/D_n (valid while D_n != 0)."""
    hs = []
    for n in range(len(D) - 1):
        if D[n] == 0:
            break
        hs.append(D[n + 1] / D[n])
    return hs


def _stj(nodes, wts, K):
    """monic orthogonal chain over a signed atomic measure (exact
    rationals); returns (al[0..K-1], be[0..K-1], hs[0..K])."""
    pk = [_Fr(1)] * len(nodes)
    pkm = [_Fr(0)] * len(nodes)
    hs = [sum(w * p * p for w, p in zip(wts, pk))]
    al, be = [], []
    for n in range(K):
        a_n = sum(w * x * p * p
                  for w, x, p in zip(wts, nodes, pk)) / hs[n]
        b_n = hs[n] / hs[n - 1] if n >= 1 else _Fr(0)
        nxt = [(x - a_n) * p - (b_n * q if n >= 1 else 0)
               for x, p, q in zip(nodes, pk, pkm)]
        pkm, pk = pk, nxt
        hs.append(sum(w * p * p for w, p in zip(wts, pk)))
        al.append(a_n)
        be.append(b_n)
    return al, be, hs


def _op_values(nodes, wts, K):
    """values of the monic OPs pi_0..pi_K of (nodes, wts) at arbitrary
    points: returns a function evalvec(x) -> [pi_0(x)..pi_K(x)], plus
    the norms hs[0..K] (three-term recurrence, exact)."""
    al, be, hs = _stj(nodes, wts, K)

    def evalvec(x):
        vals = [_Fr(1)]
        if K >= 1:
            vals.append(x - al[0])
        for n in range(1, K):
            vals.append((x - al[n]) * vals[n] - be[n] * vals[n - 1])
        return vals
    return evalvec, hs


def _node_poly_deriv(nodes, x):
    """L'(x) at a node x of L(t) = prod (t - x_j) (exact)."""
    out = _Fr(1)
    for y in nodes:
        if y != x:
            out *= (x - y)
    return out


def _split(nodes, wts):
    mu = [(x, w) for x, w in zip(nodes, wts) if w > 0]
    nu = [(x, -w) for x, w in zip(nodes, wts) if w < 0]
    return mu, nu


def _sgn(v):
    return 1 if v > 0 else (-1 if v < 0 else 0)


