def _lstar_reduction_theorems(gates):
    """The reduction dictionary: the r283 A-chain (A1-A5), the r285
    bookkeeping (B1-B2), the r282 four-language elimination (C1-C4),
    all module-own (exact Fractions plus two declared float eigen
    cross-checks), and the typed measurement pins (M1-M2) whose ground
    truth is sealed probe-side and re-verified by the embedded pattern
    gates."""
    import numpy as _np

    def chk(name, ok, detail=""):
        gates.append(bool(ok))
        print("  [%s] %s%s" % ("PASS" if ok else "FAIL", name,
                               ("  -- " + detail) if detail else ""),
              flush=True)

    print("\n" + "-" * 74)
    print("MODULE-OWN EXACT SECTION S0: the L* reduction dictionary "
          "(A1-A5 + B1-B2 + C1-C4 + M1-M2)")
    print("-" * 74, flush=True)

    # ---- per-toy exact data (chains, splits, frame objects)
    TD = {}
    for name, nodes, wts in _TOYS5 + (("POSLIKE", _XC, _POSLIKE_W),):
        if name in TD:
            continue
        S = len(nodes)
        D = _hankel_dets(nodes, wts, S)
        hs = _chain_from_dets(D)
        minC = next((n for n, h in enumerate(hs) if h < 0), None)
        Sm = sum(1 for w in wts if w < 0)
        budget = sum(1 for h in hs[:S] if h < 0)
        mu, nu = _split(nodes, wts)
        Sp = len(mu)
        TD[name] = dict(nodes=nodes, wts=wts, S=S, Nw=(S + 1) // 2,
                        D=D, hs=hs, minC=minC, Sm=Sm, Sp=Sp,
                        budget=budget, mu=mu, nu=nu)

    # ---- S0-chain-census: sealed anchors, budget theorem, signs
    ok = True
    det = []
    for name in ("JF9", "MAINLIKE", "FLIPLIKE", "POSLIKE",
                 "EPS1", "BIG1"):
        t = TD[name]
        S, Nw, minC, Sm = _ANCH[name]
        ok &= (t["S"] == S and t["Nw"] == Nw and t["minC"] == minC
               and t["Sm"] == Sm and t["budget"] == Sm)
        if name in _SIGNSTR:
            sig = "".join("+" if h > 0 else "-" for h in t["hs"][:S])
            ok &= (sig == _SIGNSTR[name])
        det.append("%s minC=%s bud=%d" % (name, t["minC"], t["budget"]))
    chk("S0-chain-census", ok,
        "sealed anchors + budget == S_- on all six toys: "
        + ", ".join(det))

    # ---- frame objects per r283 toy: minors of D_mu - G
    def frame_minors(t):
        mu, nu = t["mu"], t["nu"]
        Sp = t["Sp"]
        evalvec, hmu = _op_values([x for x, _ in mu],
                                  [w for _, w in mu], Sp - 1)
        pivals = [(v, evalvec(y)) for y, v in nu]     # (v_k, pi_i(y_k))
        M = [[(hmu[i] if i == j else _Fr(0))
              - sum(v * pv[i] * pv[j] for v, pv in pivals)
              for j in range(Sp)] for i in range(Sp)]
        minors = [_frac_det([row[:k] for row in M[:k]])
                  for k in range(1, Sp + 1)]
        return minors, hmu, pivals

    FR = {}
    for name, _n, _w in _TOYS5:
        FR[name] = frame_minors(TD[name])

    # ---- A1: mu-frame congruence minor_k(D_mu - G) == D_k(mutilde)
    ok = True
    for name, _n, _w in _TOYS5:
        minors = FR[name][0]
        D = TD[name]["D"]
        ok &= all(minors[k - 1] == D[k]
                  for k in range(1, TD[name]["Sp"] + 1))
    chk("A1-congruence", ok,
        "minor_k(D_mu - G) == D_k(mutilde) exact at every k <= S_+ "
        "on all five r283 toys (rational)")

    # ---- A1 must-fail: one-nu-atom truncation breaks the congruence
    t = TD["JF9"]
    mu, nu = t["mu"], t["nu"]
    nu_trunc = nu[:-1]                                # drop one nu atom
    evalvec, hmu = _op_values([x for x, _ in mu],
                              [w for _, w in mu], t["Sp"] - 1)
    piv_t = [(v, evalvec(y)) for y, v in nu_trunc]
    Mt = [[(hmu[i] if i == j else _Fr(0))
           - sum(v * pv[i] * pv[j] for v, pv in piv_t)
           for j in range(t["Sp"])] for i in range(t["Sp"])]
    mism = next((k for k in range(1, t["Sp"] + 1)
                 if _frac_det([row[:k] for row in Mt[:k]]) != t["D"][k]),
                None)
    dev = (abs(float(_frac_det([row[:1] for row in Mt[:1]])
                     - t["D"][1])) if mism == 1 else float("nan"))
    chk("A1-truncation-mustfail", mism is not None,
        "dropping one nu atom breaks the congruence LOUDLY (first "
        "mismatch at k = %s, k=1 dev %.2e)" % (mism, dev))

    # ---- A2: frame contraction (Sylvester side exact, eigen float
    # ---- cross-check) in BOTH truth values
